/* ============================================================================
   REV-EM — système de traduction de l'interface (i18n)
   ------------------------------------------------------------------------
   Fichier autonome, chargé AVANT le script principal (comme auth.js), pour
   que window.LyonI18n existe dès le premier rendu. Ne dépend d'aucune autre
   partie du site : pas de Supabase, pas d'accès réseau, pas de détection
   automatique de la langue du navigateur (choix explicite — voir le rapport
   d'étape : langue française par défaut, restaurée sinon depuis le dernier
   choix de l'utilisateur).

   Architecture : un dictionnaire { langue: { "namespace.cle": "texte" } },
   consulté via LyonI18n.t("namespace.cle", variables). Le reste du site
   n'écrit jamais de chaîne de langue en dur ni de if(lang === "fr") — tout
   passe par cette unique fonction, ce qui garantit qu'ajouter/mofidier une
   traduction se fait à UN seul endroit (ce fichier), pour les 5 langues.

   Portée volontairement traduite dans cette étape (voir rapport pour le
   détail) : navigation, "Mon espace"/compte, tableau de bord, écrans de
   connexion/inscription, paramètres. Le contenu pédagogique (matières,
   chapitres, questions, fiches, flashcards, cours importés par
   l'utilisateur) n'est JAMAIS traduit automatiquement — ce n'est pas
   l'objet de ce système, qui ne traduit que l'interface de l'application.
   ============================================================================ */

